nodes.summary:
Provides styles [data-component="dropdown"], position: relative;

  [data-slot="trigger"], display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-3);
    border: none;
    border-radius: var(--border-radius-sm);
    background-color: transparent;
    color: var(--color-text);
    font-size: var(--font-size-sm);
    font-family: var(--font-sans);
    cursor: pointer;
    transition: all 0.15s ease;

    &:hover, span for the associated interface in dropdown.css.

Provides styles [data-page="go"], --go-console-bg: var(--v2-grey-50);
  --go-console-surface: var(--v2-grey-100);
  --go-console-track: var(--v2-grey-200);
  --go-console-text: var(--v2-grey-1100);
  --go-console-secondary: var(--v2-grey-700);
  --go-console-muted: var(--v2-grey-600);
  --go-console-border: var(--v2-alpha-dark-8);
  --go-console-icon: var(--v2-grey-600);

  @media (prefers-color-scheme: dark), [data-component="go-plan-chart"], margin: 0;
  padding: 2rem var(--padding) 3rem;
  background: var(--go-console-bg);
  color: var(--go-console-text);
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  font-weight: 440;
  line-height: 1.25rem;
  letter-spacing: -0.04px;
  text-rendering: geometricPrecision;
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;

  [data-slot="heading"] for the associated interface in go-plan-chart.css.

Provides styles .context-menu, position: fixed;
  z-index: 1000;
  min-width: 160px;
  border-radius: 8px;
  background-color: var(--color-background);
  box-shadow:
    0 0 0 1px rgba(19, 16, 16, 0.08),
    0 6px 8px -4px rgba(19, 16, 16, 0.12),
    0 4px 3px -2px rgba(19, 16, 16, 0.12),
    0 1px 2px -1px rgba(19, 16, 16, 0.12);
  padding: 6px;

  @media (prefers-color-scheme: dark), .context-menu-item, display: flex;
  gap: 12px;
  width: 100%;
  padding: 8px 16px 8px 8px;
  font-weight: 500;
  cursor: pointer;
  background: none;
  border: none;
  align-items: center;
  color: var(--color-text);
  font-size: var(--font-size-sm);
  text-align: left;
  border-radius: 2px;
  transition: background-color 0.2s ease;

  [data-slot="copy dark"] for the associated interface in header-context-menu.css.

Provides styles [data-component="go-usage"], --model-width: 16.5rem;
  --request-width: 5.25rem;
  --allowance-width: 6.75rem;
  --column-gap: 1.5rem;
  --bar-origin: left;
  container-type: inline-size;
  margin: 0;
  padding: 3rem var(--padding) 2.5rem;
  font-variant-numeric: tabular-nums;
  scroll-margin-top: 6rem;
  -webkit-font-smoothing: antialiased;

  &:dir(rtl), [data-slot="heading"], padding-bottom: 1.5rem;

    h2 for the associated interface in limits-graph.css.

Provides styles ::selection, background: var(--color-background-interactive);
  color: var(--color-text-strong);

  @media (prefers-color-scheme: dark), [data-page="opencode"], body for the associated interface in index.css.

Provides styles field has focus. */
[data-component="browser-address"], position: relative;
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1 1 0;
  min-width: 0;
  height: 28px;
  padding-inline: 8px;
  border-radius: 6px;
  background-color: var(--v2-background-bg-layer-01);
  box-shadow: inset 0 0 0 0.5px transparent;
  color: var(--v2-text-text-base);
  font-size: 13px;
  font-weight: 440;
  line-height: var(--line-height-compact);
  letter-spacing: -0.04px;
  cursor: text;

  &[data-site], &:hover:not([data-editing]), &[data-editing] for the associated interface in bar.css.
